1	// Copyright IBM Corp. All Rights Reserved.
2	//
3	// SPDX-License-Identifier: Apache-2.0
4	//
5	
6	package bft
7	
8	import (
9		"sync"
10		"sync/atomic"
11		"time"
12	
13		"github.com/hyperledger-labs/SmartBFT/pkg/api"
14		"github.com/hyperledger-labs/SmartBFT/smartbftprotos"
15	)
16	
17	// A node could either be a leader or a follower
18	const (
19		Leader   Role = false
20		Follower Role = true
21	)
22	
23	//go:generate mockery -dir . -name HeartbeatEventHandler -case underscore -output ./mocks/
24	
25	// HeartbeatEventHandler defines who to call when a heartbeat timeout expires or a Sync needs to be triggered.
26	// This is implemented by the Controller.
27	type HeartbeatEventHandler interface {
28		// OnHeartbeatTimeout is called when a heartbeat timeout expires.
29		OnHeartbeatTimeout(view uint64, leaderID uint64)
30		// Sync is called when enough heartbeat responses report that the current leader's view is outdated.
31		Sync()
32	}
33	
34	// Role indicates if this node is a follower or a leader
35	type Role bool
36	
37	type roleChange struct {
38		view                            uint64
39		leaderID                        uint64
40		follower                        Role
41		onlyStopSendHeartbearFromLeader bool
42	}
43	
44	// heartbeatResponseCollector is a map from node ID to view number, and hold the last response from each node.
45	type heartbeatResponseCollector map[uint64]uint64
46	
47	// HeartbeatMonitor implements LeaderMonitor
48	type HeartbeatMonitor struct {
49		scheduler                     <-chan time.Time
50		inc                           chan incMsg
51		stopChan                      chan struct{}
52		commandChan                   chan roleChange
53		logger                        api.Logger
54		hbTimeout                     time.Duration
55		hbCount                       uint64
56		comm                          Comm
57		numberOfNodes                 uint64
58		handler                       HeartbeatEventHandler
59		view                          uint64
60		leaderID                      uint64
61		follower                      Role
62		stopSendHeartbearFromLeader   bool
63		lastHeartbeat                 time.Time
64		lastTick                      time.Time
65		hbRespCollector               heartbeatResponseCollector
66		running                       sync.WaitGroup
67		runOnce                       sync.Once
68		timedOut                      bool
69		syncReq                       bool
70		viewSequences                 *atomic.Value
71		sentHeartbeat                 chan struct{}
72		artificialHeartbeat           chan incMsg
73		behindSeq                     uint64
74		behindCounter                 uint64
75		numOfTicksBehindBeforeSyncing uint64
76		followerBehind                bool
77	}
78	
79	// NewHeartbeatMonitor creates a new HeartbeatMonitor
80	func NewHeartbeatMonitor(scheduler <-chan time.Time, logger api.Logger, heartbeatTimeout time.Duration, heartbeatCount uint64, comm Comm, numberOfNodes uint64, handler HeartbeatEventHandler, viewSequences *atomic.Value, numOfTicksBehindBeforeSyncing uint64) *HeartbeatMonitor {
81		hm := &HeartbeatMonitor{
82			stopChan:                      make(chan struct{}),
83			inc:                           make(chan incMsg),
84			commandChan:                   make(chan roleChange),
85			scheduler:                     scheduler,
86			logger:                        logger,
87			hbTimeout:                     heartbeatTimeout,
88			hbCount:                       heartbeatCount,
89			comm:                          comm,
90			numberOfNodes:                 numberOfNodes,
91			handler:                       handler,
92			hbRespCollector:               make(heartbeatResponseCollector),
93			viewSequences:                 viewSequences,
94			sentHeartbeat:                 make(chan struct{}, 1),
95			artificialHeartbeat:           make(chan incMsg, 1),
96			numOfTicksBehindBeforeSyncing: numOfTicksBehindBeforeSyncing,
97		}
98		return hm
99	}
100	
101	func (hm *HeartbeatMonitor) start() {
102		hm.running.Add(1)
103		go hm.run()
104	}
105	
106	// Close stops following or sending heartbeats.
107	func (hm *HeartbeatMonitor) Close() {
108		if hm.closed() {
109			return
110		}
111		defer func() {
112			hm.lastHeartbeat = time.Time{}
113			hm.lastTick = time.Time{}
114		}()
115		defer hm.running.Wait()
116		close(hm.stopChan)
117	}
118	
119	func (hm *HeartbeatMonitor) run() {
120		defer hm.running.Done()
121		for {
122			select {
123			case <-hm.stopChan:
124				return
125			case now := <-hm.scheduler:
126				hm.tick(now)
127			case msg := <-hm.inc:
128				hm.handleMsg(msg.sender, msg.Message)
129			case cmd := <-hm.commandChan:
130				hm.handleCommand(cmd)
131			case <-hm.sentHeartbeat:
132				hm.lastHeartbeat = hm.lastTick
133			case msg := <-hm.artificialHeartbeat:
134				hm.handleArtificialHeartBeat(msg.sender, msg.GetHeartBeat())
135			}
136		}
137	}
138	
139	// ProcessMsg handles an incoming heartbeat or heartbeat-response.
140	// If the sender and msg.View equal what we expect, and the timeout had not expired yet, the timeout is extended.
141	func (hm *HeartbeatMonitor) ProcessMsg(sender uint64, msg *smartbftprotos.Message) {
142		select {
143		case hm.inc <- incMsg{
144			sender:  sender,
145			Message: msg,
146		}:
147		case <-hm.stopChan:
148		}
149	}
150	
151	// InjectArtificialHeartbeat injects an artificial heartbeat to the monitor
152	func (hm *HeartbeatMonitor) InjectArtificialHeartbeat(sender uint64, msg *smartbftprotos.Message) {
153		select {
154		case hm.artificialHeartbeat <- incMsg{
155			sender:  sender,
156			Message: msg,
157		}:
158		default:
159		}
160	}
161	
162	func (hm *HeartbeatMonitor) StopLeaderSendMsg() {
163		hm.logger.Infof("Changing role to follower without change current view and current leader")
164		select {
165		case hm.commandChan <- roleChange{
166			onlyStopSendHeartbearFromLeader: true,
167		}:
168		case <-hm.stopChan:
169			return
170		}
171	}
172	
173	// ChangeRole will change the role of this HeartbeatMonitor
174	func (hm *HeartbeatMonitor) ChangeRole(follower Role, view uint64, leaderID uint64) {
175		hm.runOnce.Do(func() {
176			hm.follower = follower
177			hm.start()
178		})
179	
180		role := "leader"
181		if follower {
182			role = "follower"
183		}
184	
185		hm.logger.Infof("Changing to %s role, current view: %d, current leader: %d", role, view, leaderID)
186		select {
187		case hm.commandChan <- roleChange{
188			leaderID: leaderID,
189			view:     view,
190			follower: follower,
191		}:
192		case <-hm.stopChan:
193			return
194		}
195	}
196	
197	func (hm *HeartbeatMonitor) handleMsg(sender uint64, msg *smartbftprotos.Message) {
198		switch msg.GetContent().(type) {
199		case *smartbftprotos.Message_HeartBeat:
200			hm.handleRealHeartBeat(sender, msg.GetHeartBeat())
201		case *smartbftprotos.Message_HeartBeatResponse:
202			hm.handleHeartBeatResponse(sender, msg.GetHeartBeatResponse())
203		default:
204			hm.logger.Warnf("Unexpected message type, ignoring")
205		}
206	}
207	
208	func (hm *HeartbeatMonitor) handleRealHeartBeat(sender uint64, hb *smartbftprotos.HeartBeat) {
209		hm.handleHeartBeat(sender, hb, false)
210	}
211	
212	func (hm *HeartbeatMonitor) handleArtificialHeartBeat(sender uint64, hb *smartbftprotos.HeartBeat) {
213		hm.handleHeartBeat(sender, hb, true)
214	}
215	
216	func (hm *HeartbeatMonitor) handleHeartBeat(sender uint64, hb *smartbftprotos.HeartBeat, artificial bool) {
217		if hb.View < hm.view {
218			hm.logger.Debugf("Heartbeat view is lower than expected, sending response; expected-view=%d, received-view: %d", hm.view, hb.View)
219			hm.sendHeartBeatResponse(sender)
220			return
221		}
222	
223		if !hm.stopSendHeartbearFromLeader && sender != hm.leaderID {
224			hm.logger.Debugf("Heartbeat sender is not leader, ignoring; leader: %d, sender: %d", hm.leaderID, sender)
225			return
226		}
227	
228		if hb.View > hm.view {
229			hm.logger.Debugf("Heartbeat view is bigger than expected, syncing and ignoring; expected-view=%d, received-view: %d", hm.view, hb.View)
230			hm.handler.Sync()
231			return
232		}
233	
234		active, ourSeq := hm.viewActive(hb)
235		if active && !artificial {
236			if ourSeq+1 < hb.Seq {
237				hm.logger.Debugf("Heartbeat sequence is bigger than expected, leader's sequence is %d and ours is %d, syncing and ignoring", hb.Seq, ourSeq)
238				hm.handler.Sync()
239				return
240			}
241			if ourSeq+1 == hb.Seq {
242				hm.followerBehind = true
243				hm.logger.Debugf("Our sequence is behind the heartbeat sequence, leader's sequence is %d and ours is %d", hb.Seq, ourSeq)
244				if ourSeq > hm.behindSeq {
245					hm.behindSeq = ourSeq
246					hm.behindCounter = 0
247				}
248			} else {
249				hm.followerBehind = false
250			}
251		} else {
252			hm.followerBehind = false
253		}
254	
255		hm.logger.Debugf("Received heartbeat from %d, last heartbeat was %v ago", sender, hm.lastTick.Sub(hm.lastHeartbeat))
256		hm.lastHeartbeat = hm.lastTick
257	}
258	
259	// handleHeartBeatResponse keeps track of responses, and if we get f+1 identical, force a sync
260	func (hm *HeartbeatMonitor) handleHeartBeatResponse(sender uint64, hbr *smartbftprotos.HeartBeatResponse) {
261		if hm.follower {
262			hm.logger.Debugf("Monitor is not a leader, ignoring HeartBeatResponse; sender: %d, msg: %v", sender, hbr)
263			return
264		}
265	
266		if hm.syncReq {
267			hm.logger.Debugf("Monitor already called Sync, ignoring HeartBeatResponse; sender: %d, msg: %v", sender, hbr)
268			return
269		}
270	
271		if hm.view >= hbr.View {
272			hm.logger.Debugf("Monitor view: %d >= HeartBeatResponse, ignoring; sender: %d, msg: %v", hm.view, sender, hbr)
273			return
274		}
275	
276		hm.logger.Debugf("Received HeartBeatResponse, msg: %v; from %d", hbr, sender)
277		hm.hbRespCollector[sender] = hbr.View
278	
279		// check if we have f+1 votes
280		_, f := computeQuorum(hm.numberOfNodes)
281		if len(hm.hbRespCollector) >= f+1 {
282			hm.logger.Infof("Received HeartBeatResponse triggered a call to HeartBeatEventHandler Sync, view: %d", hbr.View)
283			hm.handler.Sync()
284			hm.syncReq = true
285		}
286	}
287	
288	func (hm *HeartbeatMonitor) sendHeartBeatResponse(target uint64) {
289		heartbeatResponse := &smartbftprotos.Message{
290			Content: &smartbftprotos.Message_HeartBeatResponse{
291				HeartBeatResponse: &smartbftprotos.HeartBeatResponse{
292					View: hm.view,
293				},
294			},
295		}
296		hm.comm.SendConsensus(target, heartbeatResponse)
297		hm.logger.Debugf("Sent HeartBeatResponse view: %d; to %d", hm.view, target)
298	}
299	
300	func (hm *HeartbeatMonitor) viewActive(hbMsg *smartbftprotos.HeartBeat) (bool, uint64) {
301		vs := hm.viewSequences.Load()
302		// View isn't initialized
303		if vs == nil {
304			return false, 0
305		}
306	
307		viewSeq := vs.(ViewSequence)
308		if !viewSeq.ViewActive {
309			return false, 0
310		}
311	
312		return true, viewSeq.ProposalSeq
313	}
314	
315	func (hm *HeartbeatMonitor) tick(now time.Time) {
316		hm.lastTick = now
317		if hm.lastHeartbeat.IsZero() {
318			hm.lastHeartbeat = now
319		}
320		if bool(hm.follower) || hm.stopSendHeartbearFromLeader {
321			hm.followerTick(now)
322		} else {
323			hm.leaderTick(now)
324		}
325	}
326	
327	func (hm *HeartbeatMonitor) closed() bool {
328		select {
329		case <-hm.stopChan:
330			return true
331		default:
332			return false
333		}
334	}
335	
336	func (hm *HeartbeatMonitor) handleCommand(cmd roleChange) {
337		if cmd.onlyStopSendHeartbearFromLeader {
338			hm.stopSendHeartbearFromLeader = true
339			return
340		}
341	
342		hm.stopSendHeartbearFromLeader = false
343		hm.view = cmd.view
344		hm.leaderID = cmd.leaderID
345		hm.follower = cmd.follower
346		hm.timedOut = false
347		hm.lastHeartbeat = hm.lastTick
348		hm.hbRespCollector = make(heartbeatResponseCollector)
349		hm.syncReq = false
350	}
351	
352	func (hm *HeartbeatMonitor) leaderTick(now time.Time) {
353		if now.Sub(hm.lastHeartbeat)*time.Duration(hm.hbCount) < hm.hbTimeout {
354			return
355		}
356	
357		var sequence uint64
358		vs := hm.viewSequences.Load()
359		if vs != nil && vs.(ViewSequence).ViewActive {
360			sequence = vs.(ViewSequence).ProposalSeq
361		} else {
362			hm.logger.Infof("ViewSequence uninitialized or view inactive")
363			return
364		}
365		hm.logger.Debugf("Sending heartbeat with view %d, sequence %d", hm.view, sequence)
366		heartbeat := &smartbftprotos.Message{
367			Content: &smartbftprotos.Message_HeartBeat{
368				HeartBeat: &smartbftprotos.HeartBeat{
369					View: hm.view,
370					Seq:  sequence,
371				},
372			},
373		}
374		hm.comm.BroadcastConsensus(heartbeat)
375		hm.lastHeartbeat = now
376	}
377	
378	func (hm *HeartbeatMonitor) followerTick(now time.Time) {
379		if hm.timedOut || hm.lastHeartbeat.IsZero() {
380			hm.lastHeartbeat = now
381			return
382		}
383	
384		delta := now.Sub(hm.lastHeartbeat)
385		if delta >= hm.hbTimeout {
386			hm.logger.Warnf("Heartbeat timeout (%v) from %d expired; last heartbeat was observed %s ago",
387				hm.hbTimeout, hm.leaderID, delta)
388			hm.handler.OnHeartbeatTimeout(hm.view, hm.leaderID)
389			hm.timedOut = true
390			return
391		}
392	
393		hm.logger.Debugf("Last heartbeat from %d was %v ago", hm.leaderID, delta)
394	
395		if !hm.followerBehind {
396			return
397		}
398	
399		hm.behindCounter++
400		if hm.behindCounter >= hm.numOfTicksBehindBeforeSyncing {
401			hm.logger.Warnf("Syncing since the follower with seq %d is behind the leader for the last %d ticks", hm.behindSeq, hm.numOfTicksBehindBeforeSyncing)
402			hm.handler.Sync()
403			hm.behindCounter = 0
404			return
405		}
406	}
407	
408	// HeartbeatWasSent tells the monitor to skip sending a heartbeat
409	func (hm *HeartbeatMonitor) HeartbeatWasSent() {
410		select {
411		case hm.sentHeartbeat <- struct{}{}:
412		default:
413		}
414	}
